WITH exploded AS (SELECT id, plan, EXPLODE_OUTER(tier_prices) AS element FROM price_tiers), base AS (SELECT *, INITCAP(TRIM(plan)) AS plan_title, CASE WHEN plan IN ('pro', 'basic') THEN 'Tier 1' ELSE 'Other' END AS plan_group FROM exploded WHERE element >= 75), enriched AS (SELECT id, plan_title, DENSE_RANK() OVER (PARTITION BY plan ORDER BY element NULLS FIRST) AS element_dense_rank, MIN(element) OVER (PARTITION BY plan) AS plan_min_element, RANK() OVER (PARTITION BY plan ORDER BY element DESC) AS element_rank FROM base), metrics AS (SELECT *, CUME_DIST() OVER (ORDER BY element_dense_rank DESC) AS element_dense_rank_cume_dist FROM enriched WHERE element_rank = 4), scored AS (SELECT *, CUME_DIST() OVER (ORDER BY element_rank NULLS LAST) AS element_rank_cume_dist FROM metrics), stats AS (SELECT CASE WHEN plan_min_element >= 81 THEN 'HIGH' ELSE 'LOW' END AS plan_min_element_tier, PERCENTILE_APPROX(plan_min_element, ARRAY(0.25, 0.5, 0.75)) AS plan_min_element_quartiles, SUM(element_rank) AS total_element_rank, APPROX_PERCENTILE(element_dense_rank_cume_dist, 0.5) AS element_dense_rank_cume_dist_p50 FROM scored GROUP BY CASE WHEN plan_min_element >= 81 THEN 'HIGH' ELSE 'LOW' END) SELECT plan_min_element_tier, total_element_rank, element_dense_rank_cume_dist_p50 FROM stats
